#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")/.."
DEPLOY_ROOT="${DEPLOY_ROOT:-$PWD/production}"
if [[ ! -f "$DEPLOY_ROOT/active.env" ]]; then
  echo "No active deployment. Run bash scripts/deploy.sh first." >&2
  exit 1
fi
# active.env is generated by this project's deploy script (not untrusted input).
source "$DEPLOY_ROOT/active.env"
check() { bash scripts/health-check.sh "http://127.0.0.1:$ACTIVE_PORT" "$DEPLOY_ROOT/monitoring.log"; }
if [[ "${1:---once}" == "--watch" ]]; then
  while true; do check || true; sleep "${MONITOR_INTERVAL:-15}"; done
else
  check
fi
